import org.junit.Test;
import static org.junit.Assert.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;

public class UrlBuilderTest {

    private static final ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    private static final PrintStream originalOut = System.out;
    private final UrlBuilder urlBuilder = new UrlBuilder("https://example.com");

    @Test
    public void testAppendKeyVal() {
        urlBuilder.appendKeyVal(new org.jsoup.helper.KeyValueMap());
        assertTrue(outputStream.toString().contains("https://example.com"));
    }

    @Test
    public void testAppendKeyVal_Empty KvMap() {
        urlBuilder.appendKeyVal(new org.jsoup.helper.KeyValueMap());
        assertFalse(outputStream.toString().contains("https://example.com"));
    }

    @Test
    public void testAppendKeyVal_UnsupportedEncodingException() throws UnsupportedEncodingException {
        urlBuilder.appendKeyVal(new org.jsoup.helper.KeyValueMap());
        assertThrows(UnsupportedEncodingException.class, () -> urlBuilder.appendKeyVal(null));
    }

    @Test
    public void testBuild() {
        String inputUrl = "https://example.com";
        URL outputUrl = urlBuilder.build();
        assertEquals(inputUrl, outputUrl);
    }

    @Test
    public void testBuild_EmptyInputUrl() {
        assertThrows(UnsupportedEncodingException.class, () -> urlBuilder.build());
    }

    @Test
    public void testAppendKeyVal_Invalid KvMapElement() {
        urlBuilder.appendKeyVal(new org.jsoup.helper.KeyValueMap("invalid", "key"));
        assertFalse(outputStream.toString().contains("https://example.com"));
    }
}
